{
  "decision": "PROCEED_WITH_GAP",
  "reason": "The knowledge base supports audit records, data migration, and REST API integration, but lacks evidence for browser signing, automated reminders within 72 hours, template provisions, ten-year document storage, and an on-premises deployment option.",
  "claims": [
    {
      "kind": "capability",
      "text": "Every change to a case is logged with the user, the time and the previous value, supporting audit records of signature events.",
      "evidence_ids": [
        "CAP-004"
      ],
      "src_ids": [
        "SRC-0020"
      ]
    },
    {
      "kind": "capability",
      "text": "Migration of historic records and documents is supported, including trial runs, reconciliation reports and a final cut-over.",
      "evidence_ids": [
        "CAP-007"
      ],
      "src_ids": [
        "SRC-0026"
      ]
    },
    {
      "kind": "capability",
      "text": "A documented REST API and webhooks are provided for exchanging data with other line-of-business systems.",
      "evidence_ids": [
        "CAP-006"
      ],
      "src_ids": [
        "SRC-0027"
      ]
    }
  ],
  "gap": "No evidence for supporting signing on current desktop and mobile browsers, sending a reminder within 72 hours, providing templates for the College's twelve most used forms, storing signed documents for ten years, or proposing an on-premises deployment option.",
  "question": null
}

